// D560 — the text and scrape models the free features call, and their ai_models rows
// (migration 0082). Ids are provider-prefixed; the call sites use the bare model name.
import type { AiModelSeedRow } from "./seed";

export const TEXT_MODEL_IDS = [
  "openai:gpt-5", "openai:gpt-4o-mini",
  "gemini:gemini-3.1-pro-preview", "gemini:gemini-3.8-flash", "gemini:gemini-3.5-flash-lite",
] as const;
export const APIFY_MODEL_ID = "apify:actor";

export const TEXT_SEED_HEADER = [
  "-- D537: the text and scrape models the free features call.",
  "-- Generated by src/lib/ai-models/text-models.ts. Regenerate with:",
  "--   UPDATE_SEED=1 npx vitest run src/lib/ai-models/__tests__/text-models.test.ts",
];

const row = (
  id: string, provider: string, kind: AiModelSeedRow["kind"], label: string, providerLabel: string,
  sortOrder: number,
): AiModelSeedRow => ({
  id, provider, kind, label, picker_label: null, provider_label: providerLabel, status: "live",
  replaced_by: null, sort_order: sortOrder, adapter_key: `${kind}:${provider}`,
  params: [], rules: [], capabilities: {},
});

export function textModelRows(): AiModelSeedRow[] {
  return [
    row("openai:gpt-5", "openai", "text", "GPT-5", "OpenAI", 1),
    row("openai:gpt-4o-mini", "openai", "text", "GPT-4o mini", "OpenAI", 2),
    row("gemini:gemini-3.1-pro-preview", "gemini", "text", "Gemini 3.1 Pro", "Google", 0),
    row("gemini:gemini-3.8-flash", "gemini", "text", "Gemini 3.8 Flash", "Google", 1),
    row("gemini:gemini-3.5-flash-lite", "gemini", "text", "Gemini 3.5 Flash Lite", "Google", 2),
    row(APIFY_MODEL_ID, "apify", "scrape", "Web scraping", "Apify", 0),
  ];
}
